from dataclasses import dataclass
from typing import List, Dict, Optional

@dataclass
class DiscountCode:
    code: str
    discount_rate: float

class Cart:
    _discount_registry: Dict[str, DiscountCode] = {
        'SAVE10': DiscountCode('SAVE10', 0.10),
        'SAVE20': DiscountCode('SAVE20', 0.20),
        'HALFOFF': DiscountCode('HALFOFF', 0.50)
    }

    def __init__(self):
        self.items: List[Dict[str, float | int]] = []
        self.discount_code: Optional[str] = None

    def add_item(self, name: str, price: float, qty: int) -> None:
        self.items.append({'name': name, 'price': price, 'qty': qty})

    @property
    def subtotal(self) -> float:
        return sum(item['price'] * item['qty'] for item in self.items)

    @property
    def discount(self) -> float:
        if self.discount_code not in self._discount_registry:
            return 0.0
        return self.subtotal * self._discount_registry[self.discount_code].discount_rate

    def get_tax(self) -> float:
        return (self.subtotal - self.discount) * 0.08

    def get_total(self) -> float:
        return self.subtotal - self.discount + self.get_tax()
